const gasHex = items[0]?.json?.result;
const timestamp = Date.now();
const idempotencyKey = `gas_sync_${Math.floor(timestamp / 300000)}`;

if (typeof gasHex !== 'string' || !/^0x[0-9a-fA-F]+$/.test(gasHex)) {
  return [{ json: { error: 'invalid_gas_result', raw: gasHex, idempotencyKey, timestamp, valid: false } }];
}

const gasGwei = parseInt(gasHex, 16) / 1e9;
if (!isFinite(gasGwei)) {
  return [{ json: { error: 'non_finite_gas_result', raw: gasHex, idempotencyKey, timestamp, valid: false } }];
}

return [{ json: { gasGwei, idempotencyKey, timestamp, valid: true } }];

